{
  "greeting": "Dear Sir/Madam,",
  "paragraphs": [
    "My name is Darcy Oakes, and I have recently joined Harlan Oakes CPA as office manager and billing coordinator. Going forward, I will be handling billing and general correspondence.",
    "Please find attached herewith our invoice INV-2026-0008 for the July 2026 retainer period, referencing PO-CWB-2026-1446. The invoice covers professional advisory services and accounting support services for the month, including PBC/workpaper support, close assistance, and general advisory.",
    "Harlan is presently traveling, so I am assisting with invoicing in his absence.",
    "Would you kindly confirm receipt at your convenience?"
  ],
  "closing": "Sincerely,",
  "signature": {
    "name": "Darcy Oakes",
    "title": "Office Manager / Billing Coordinator",
    "company": "Harlan Oakes CPA",
    "email": "darcy@harlanoackes.com"
  }
}

{
  "message": {
    "greeting": "Dear Sir/Madam,",
    "paragraphs": [
      "I hope you are well. I am writing to follow up politely regarding invoice INV-2026-0008 (PO-CWB-2026-1446) to confirm it has been received on your end.",
      "Our office will be closed the week of September 8–12 for the Labor Day holiday period and a planned office move, and I would be grateful for confirmation prior to then so I may reconcile our accounts receivable before the closure.",
      "Thank you in advance for your assistance."
    ],
    "closing": "Sincerely,",
    "signature": {
      "name": "Darcy Oakes",
      "title": "Office Manager / Billing Coordinator",
      "company": "Harlan Oakes CPA",
      "email": "darcy@harlanoackes.com"
    }
  },
  "quoted_reply": {
    "from": "Darcy Oakes <darcy@harlanoackes.com>",
    "date": "2026-08-14",
    "subject": "INV-2026-0008 — July 2026 Retainer (PO-CWB-2026-1446)",
    "to": "accountspayable@cedarwellbank.com",
    "cc": "jtrusdale@cedarwellbank.com; lsummerlin@cedarwellbank.com",
    "body": "Dear Sir/Madam,\n\nMy name is Darcy Oakes, and I have recently joined Harlan Oakes CPA as office manager and billing coordinator. Going forward, I will be handling billing and general correspondence.\n\nPlease find attached herewith our invoice INV-2026-0008 for the July 2026 retainer period, referencing PO-CWB-2026-1446. The invoice covers professional advisory services and accounting support services for the month, including PBC/workpaper support, close assistance, and general advisory.\n\nHarlan is presently traveling, so I am assisting with invoicing in his absence.\n\nWould you kindly confirm receipt at your convenience?\n\nSincerely,\nDarcy Oakes"
  }
}

